1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.support.GeneratedKeyHolder;
6	import org.springframework.jdbc.support.KeyHolder;
7	import org.springframework.stereotype.Repository;
8	
9	/** Data access for {@link Project} rows (JdbcTemplate over the schema in V3__projects.sql). */
10	@Repository
11	public class ProjectRepository {
12	
13	    private final JdbcTemplate jdbc;
14	
15	    public ProjectRepository(JdbcTemplate jdbc) {
16	        this.jdbc = jdbc;
17	    }
18	
19	    private static final org.springframework.jdbc.core.RowMapper<Project> MAPPER =
20	            (rs, i) -> new Project(rs.getLong("id"), rs.getString("name"),
21	                    rs.getLong("client_id"), rs.getString("client_name"),
22	                    rs.getBoolean("archived"));
23	
24	    private static final String SELECT =
25	            "SELECT p.id, p.name, p.client_id, p.archived, c.name AS client_name"
26	                    + " FROM projects p JOIN clients c ON p.client_id = c.id";
27	
28	    /**
29	     * List projects. Archived projects are hidden unless {@code includeArchived} is true — that is
30	     * what keeps a tucked-away project off the main list until the toggle reveals it.
31	     */
32	    public List<Project> findAll(boolean includeArchived) {
33	        String where = includeArchived ? "" : " WHERE p.archived = FALSE";
34	        return jdbc.query(SELECT + where + " ORDER BY p.id", MAPPER);
35	    }
36	
37	    /**
38	     * Projects carrying a given tag — backs the "filter my projects by label" dropdown. Archived
39	     * projects are hidden unless {@code includeArchived} is true, matching the plain list.
40	     */
41	    public List<Project> findByTag(long tagId, boolean includeArchived) {
42	        String archived = includeArchived ? "" : " AND p.archived = FALSE";
43	        return jdbc.query(
44	                SELECT + " JOIN project_tags pt ON pt.project_id = p.id"
45	                        + " WHERE pt.tag_id = ?" + archived + " ORDER BY p.id",
46	                MAPPER, tagId);
47	    }
48	
49	    /** Projects done for one client — reused by the client detail view. Archived ones are hidden. */
50	    public List<Project> findByClient(long clientId) {
51	        return jdbc.query(SELECT + " WHERE p.client_id = ? AND p.archived = FALSE ORDER BY p.id",
52	                MAPPER, clientId);
53	    }
54	
55	    public Project create(String name, long clientId) {
56	        KeyHolder keys = new GeneratedKeyHolder();
57	        jdbc.update(con -> {
58	            var ps = con.prepareStatement(
59	                    "INSERT INTO projects (name, client_id) VALUES (?, ?)", new String[] {"id"});
60	            ps.setString(1, name);
61	            ps.setLong(2, clientId);
62	            return ps;
63	        }, keys);
64	        String clientName = jdbc.queryForObject(
65	                "SELECT name FROM clients WHERE id = ?", String.class, clientId);
66	        return new Project(keys.getKey().longValue(), name, clientId, clientName, false);
67	    }
68	
